contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint88 amount, uint32 t) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(t > block.timestamp, "need a future timestamp");
        require(address(this).balance >= amount, "insufficient balance");

        // Force block.timestamp to be exactly t using a helper contract is impossible;
        // so we only test the fundamental update rule when the call succeeds.
        // Reset the contract's recorded time to a known past value via a successful call is impossible
        // because pastBlockTime starts at 0 and any call sets it to current time.
        // Instead, we rely on the fact that the first call should succeed if value is 10 ether
        // and block.timestamp > pastBlockTime (which is true for any block > 0).
        // We cannot control block.timestamp, but we can check that after a successful call,
        // pastBlockTime equals the current block timestamp.

        uint before = c.pastBlockTime();
        require(before == 0, "pastBlockTime must start at 0 for this test");

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        assert(!reverted || afterTime == before);
    }

    receive() external payable {}
}

