contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Ensure the initial timestamp is less than the current block timestamp.
        // This is a setup call; if the block timestamp is not greater than
        // the current stored timestamp, the condition is not met and the
        // postcondition below does not apply.
        bool setupOk;
        try c.fallback{value: amount}() {
            setupOk = true;
        } catch {
            setupOk = false;
        }

        if (setupOk) {
            uint timestampAfterSetup = c.pastBlockTime();
            require(timestampAfterSetup == block.timestamp, "setup timestamp mismatch");

            // Roll the block forward so that the next fallback call sees a
            // strictly greater timestamp.
            // (In the test environment, a second call in the same transaction
            // would see the same timestamp; this rule is intended to hold for
            // every successful fallback call that is allowed by the timestamp
            // guard.)
            uint balBefore = address(c).balance;
            bool reverted;
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (!reverted) {
                assert(c.pastBlockTime() == block.timestamp);
            } else {
                assert(c.pastBlockTime() == timestampAfterSetup);
            }
        }
    }

    receive() external payable {}
}

