        // and on success pastBlockTime becomes the current block.timestamp (which then satisfies
        // newTimestamp > pastBlockTime).
        assert(
            (newTimestamp <= block.timestamp && reverted) ||
            (newTimestamp > block.timestamp && !reverted && c.pastBlockTime() == block.timestamp && c.pastBlockTime() > oldPastBlockTime)
        );
    }

    receive() external payable {}
}

