contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 ts) public payable {
        // The fallback accepts exactly 10 ether; we must supply that amount.
        uint256 amount = 10 ether;
        require(address(this).balance >= amount);

        // Ensure the time rule is not violated.
        require(ts > block.timestamp);

        // Set the timestamp observed by c when we call it.
        // (solidity provides no direct way to set block.timestamp from a test, but we can
        // use the fact that the test harness controls the block environment; we instead
        // parameter is used as a hook for plausible timestamp and the require below
        // ensures the current block timestamp is already above c.pastBlockTime().)
        require(block.timestamp > c.pastBlockTime());

        uint256 beforeBalance = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        (reverted) = callFallback(amount);

        if (!reverted) {
            // Successful call must have swept the entire prior balance of c to this test contract.
            // This test contract started with beforeBalance, paid amount, and received cBalanceBefore.
            assert(address(this).balance == beforeBalance - amount + cBalanceBefore);
            // The timestamp recorded by c must have been updated to the call's block timestamp.
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            // If the call reverted, nothing should have changed.
            assert(address(this).balance == beforeBalance);
            assert(address(c).balance == cBalanceBefore);
        }
    }

    function callFallback(uint256 amount) private returns (bool reverted) {
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;
    }

    receive() external payable {}
}

