contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timestamp) public payable {
        require(amount >= 10 ether, "need at least 10 ether to send");
        require(address(this).balance >= amount, "test balance insufficient");

        // Setup state needed for the rule: make the first valid call so pastBlockTime is set.
        // The test contract deployed c, so this call is allowed by the no-new-deployment rule.
        uint firstBalance = address(c).balance;
        c.fallback{value: 10 ether}();
        uint secondBalance = address(c).balance;
        require(secondBalance == firstBalance + 10 ether, "setup call did not transfer 10 ether");

        uint storedBefore = c.pastBlockTime();
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint storedAfter = c.pastBlockTime();
        uint cBalanceAfter = address(c).balance;

        // General rule: if the call did not revert, it must have sent exactly 10 ether,
        // advanced pastBlockTime to a strictly greater timestamp, and if the current
        // block number is divisible by 15, drained the entire prior balance to the caller.
        // If it reverted, pastBlockTime and c's balance must be unchanged.
        if (!reverted) {
            assert(
                amount == 10 ether
                && storedAfter > storedBefore
                && storedAfter == block.timestamp
                && cBalanceAfter == cBalanceBefore + 10 ether
                && (block.number % 15 != 0 || cBalanceAfter == 0)
            );
        } else {
            assert(storedAfter == storedBefore && cBalanceAfter == cBalanceBefore);
        }
    }

    receive() external payable {}
}

