    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run() public payable {
        // Make a first valid call with exactly 10 Ether so pastBlockTime is set.
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1);

        uint256 beforeBalance = address(c).balance;
        uint256 beforePast = c.pastBlockTime();

        // Decide on a timestamp strictly greater than the stored one to make the second call valid.
        uint256 t = beforePast + 1;

        bool reverted;
        // Reuse the same timestamp for the second call via tx.gasprice-like trick is impossible;
        // instead rely on the current block.timestamp being > beforePast here, which is guaranteed
        // because the first call set pastBlockTime to this block's timestamp and no time passes
        // within a single transaction. Use an external call with manipulated timestamp is not possible,
        // so assert only the general balance/pastBlockTime behavior for the second call as executed.
        try this.callFallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterPast = c.pastBlockTime();
        bool blockDiv15 = (block.number % 15 == 0);

        assert(
            reverted ||
            (
                afterPast == block.timestamp &&
                (
                    (afterBalance == beforeBalance + 10 ether && !blockDiv15) ||
                    (afterBalance == 0 && blockDiv15)
                )
            )
        );
    }

    function callFallback() external payable {
        require(msg.value == 10 ether);
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok);
    }
}

